# -*- coding: utf-8 -*-
# Görevler: yapı (veren, teslim alan, hedef, adet, zincir, altın ve eşya ödülü) Android sürümünün çözülmüş görev tablosundan,
# metinler aşağıda elle Türkçe ve İngilizceye çevrildi. Görev hedefi cümlesi oyunda adlardan kendiliğinden kurulur.
# Kullanım (depo kökünden): python3 tools/gorevler.py     Çıktı: www/js/quests_gen.js
import json, re
T = {x['id']: x for x in json.load(open('kaynak/apk/cikti/metin/config/1025.txt', encoding='utf-8'))['tasks']}
D = json.load(open('www/assets/data.json', encoding='utf-8')); S = D['scenes']
npc = lambda i: (D['cit'].get(str(i)) or [None])[0]
def scene_of(mon):
    for k, s in S.items():
        if any(e[1] == mon for e in s['ents']): return k
# id: (tür, [toplanan eşya kaynağı canavar], başlık TR, başlık EN, metin TR, metin EN, beklerken TR, EN, bitince TR, EN, [eşya adı TR, EN])
OK = ('Kabul', 'Accept')
Q = {
# ===== Karanlık Gözcü Kulesi =====
82912: ('kill', None, 'Kan Ver!', 'Give Blood!', 'Ne zaman Sessiz Koru\'ya odun kesmeye gitsem şu ☆Kan Emici Periler kanımı emiyor. Kanım o kadar mı lezzetli? Şimdi kan vermenin tadına onlar baksın!', 'Whenever I go logging in the Silent Woodland those ☆Bloodsucking Fairies drain my blood. Is it really that tasty? Now let them have a taste of giving blood!', 'Sen de kan verdin mi?', 'Have you given blood too?', 'Hah hah, sonunda kanın bedelini ödediler!', 'Ha ha, they finally paid the price in blood!'),
82913: ('kill', None, 'Trollerin Misillemesi', 'The Trolls Strike Back', 'George Gölge Trollerini defalarca rahatsız etti; öfkelendiler ve misillemeye hazırlanıyorlar. Onlar saldırmadan planlarını bozmanı istiyorum. Birkaç trol öldür ki akılları başlarına gelsin.', 'George kept harassing the Shadow Trolls until they got angry, and now they are preparing to strike back. Ruin their plan before they do. Kill some trolls so they learn to behave.', 'Tam bir baş belası.', 'What a troublemaker.', 'Harika, planlarını durdurdun.', 'Wonderful, you stopped their plan.'),
82914: ('talk', None, 'George\'u Uyar', 'A Warning for George', 'George\'a söyle, bir daha trollere bulaşmasın. Yoksa generale söylerim, ömrünün sonuna kadar trollerle yaşar.', 'Tell George to stop provoking the trolls, or I will tell the General and he can live with the trolls for the rest of his life.', 'Ona ilet lütfen.', 'Pass it on to him.', 'Ah, işin bu kadar büyüyeceğini düşünmemiştim. Uyarın için sağ ol.', 'Oh, I never thought it would get this serious. Thanks for the warning.'),
82915: ('collect', '林地夜行者', 'Gece Avcısı Zehri', 'Nightstalker Venom', 'Son günlerde art arda zehirlenmeler oluyor. Koru Gece Avcılarının ısırdığından şüpheleniyorum. Panzehir yapabilmem için bana onların zehrinden topla.', 'There has been a string of poisonings lately. I suspect bites from Woodland Nightstalkers. Collect some of their venom so I can make an antidote.', 'Sakın ısırılma.', 'Do not get bitten.', 'Harika, hemen panzehiri hazırlamalıyım.', 'Great, I must prepare the antidote at once.', 'Gece Avcısı Zehri', 'Nightstalker Venom'),
82916: ('kill', None, 'Korku Muhafızları', 'Fear Guards', 'Tarikat Üssü\'ndeki ☆Korku Muhafızlarına dikkat et; aklını bulandırır, soydaşları birbirine kırdırırlar. İnancını sağlam tutarsan onları yenersin.', 'Beware the ☆Fear Guards of the Cult Base. They cloud your mind and turn kin against kin. Keep your faith firm and you will defeat them.', 'Sakın beynini yıkamalarına izin verme.', 'Do not let them brainwash you.', '☆Korku Muhafızlarını yendin.', 'You defeated the ☆Fear Guards.'),
82917: ('kill', None, 'Örümcek Ailesi (1)', 'The Spider Family (1)', 'Ağlı Koru\'da büyük bir tehdit var: kraliçeleri ordu topluyor. İlk işimiz bu toplanmayı engellemek. Güç peşindeki Ağ Ören Zehirli Örümcekler kraliçeye katılıyor; sayılarını azaltmalısın.', 'A great threat lurks in the Webbed Woodland: their queen is gathering an army. Our first task is to stop it. The Webspinner Venom Spiders are joining her in search of power, so thin their numbers.', 'Örümceklerin ailesi kalabalıktır.', 'Spiders have very large families.', 'İyi iş çıkardın. Sıradaki adıma geçelim.', 'Well done. On to the next step.'),
82918: ('kill', None, 'Örümcek Ailesi (2)', 'The Spider Family (2)', 'Ağlı Koru\'daki Kılıç Örümceği ordusu kraliçenin öncü birliği. Onları yok edersek kraliçenin yuvasını ele geçirebiliriz. Bu zorlu görevi başarabilir misin?', 'The Sword Spider army of the Webbed Woodland is the queen\'s vanguard. Wipe them out and we can take her nest. Can you handle this hard task?', 'Kılıç Örümceklerinin kılıcına dikkat et.', 'Watch out for the Sword Spiders\' blades.', 'İyi iş çıkardın. Kraliçenin savunma hattını yardık.', 'Well done. We have broken through the queen\'s defenses.'),
82919: ('kill', None, 'Örümcek Ailesi (3)', 'The Spider Family (3)', 'Lanet olsun, şu ☆Örümcek Muhafızlar da nereden çıktı? Bu son savunma hattı olmalı; kraliçeyle yüzleşmek üzereyiz. Bu hattı ancak sen yarabilirsin.', 'Damn it, where did those ☆Spider Guards come from? This must be the last line of defense. We are about to face the queen, and only you can break through.', 'Tehdit bitmek üzere.', 'The threat is almost gone.', 'Sonunda kraliçeyle yüzleşeceğiz.', 'At last we will face the queen.'),
82920: ('kill', None, 'Örümcek Ailesi (4)', 'The Spider Family (4)', 'Sonuna geldik. Hilekâr Kraliçe ile son savaşı yapacağız. Hazır mısın?', 'We have reached the end. It is time for the final battle with the Deceiver Queen. Are you ready?', 'Korktun mu?', 'Are you scared?', 'Sonunda kraliçeyi yendik.', 'We have finally defeated the queen.'),
82922: ('kill', None, 'Yozlaşmış Bilginler', 'Fallen Scholars', 'Yozlaşmış Bilginler büyüleriyle bütün Kayıp Koru\'yu bozdu: bitkiler çürüyor, hayvanlar değişiyor. Bana yardım et, o bilginleri öldür; canlılar daha fazla yozlaşmasın.', 'The Fallen Scholars have corrupted the whole Lost Woodland with their sorcery. Plants are rotting and animals are mutating. Help me: kill those scholars before more creatures fall.', 'Sakın orada sen de yozlaşma.', 'Do not fall there yourself.', 'Harika, onları kurtardın.', 'Wonderful, you saved them.'),
82923: ('collect', '堕落学者', 'Bilgin Cübbesi', 'Scholar\'s Coat', 'Derler ki Kayıp Koru\'daki Yozlaşmış Bilginlere hiçbir zehir işlemezmiş. Sırları ne? İpucunu cübbelerinde arayacağım. Bana birkaç tane getirebilir misin?', 'They say no poison can harm the Fallen Scholars of the Lost Woodland. What is their secret? I want to look for clues in their coats. Can you bring me a few?', 'Hekimliğim çok iyidir.', 'I am a very skilled healer.', 'Bana biraz zaman ver, incelemeye başlıyorum.', 'Give me some time, I will start my research.', 'Bilgin Cübbesi', 'Scholar\'s Coat'),
82924: ('kill', None, 'Ruhları Koru', 'Guard the Souls', 'Tarikat Üssü\'nde Ruh Biçiciler insan ruhlarını acımasızca yok ediyor. Ruhları korumalıyız; bunun en iyi yolu Ruh Biçicileri yok etmek. Onlarla yüzleşecek yüreğin var mı?', 'In the Cult Base the Soul Reapers are mercilessly erasing human souls. We must guard the souls, and the best way is to destroy the reapers. Do you dare to face them?', 'Ruhuna dikkat et.', 'Mind your soul.', 'Yardımın sayesinde ruhları koruduk.', 'Thanks to you, we kept the souls safe.'),
82925: ('kill', None, 'Beyinsiz Zombiler', 'Brainless Zombies', 'Heh heh, şu zombilerle oynamaya bayılırım; başsız sinekler gibi oraya buraya koşarlar. Beyinleri yok, hepsi ahmak. Artık bu bölgeden yok olmalarını istiyorum. Ne yapacağını biliyorsun, değil mi?', 'Heh heh, I love playing with those zombies. They run around like headless flies. No brains, all idiots. Now I want them gone from this area. You know what to do, right?', 'Zombilere de ki: gelin biraz oynayalım.', 'Tell the zombies: come and play for a while.', 'Hah hah, gerçekten beyinleri yokmuş.', 'Ha ha, they really have no brains.'),
82926: ('collect', '☆仙子邪术师', 'Büyü Tozu', 'Sorcery Dust', 'Her derde deva bir ilaç malzemesi buldum: Kayıp Koru\'daki perilerin üstünde. Onlardan biraz toz getirebilirsen George\'un bel ağrısını iyileştirebilirim.', 'I have found an ingredient that cures everything, and the fairies of the Lost Woodland carry it. Bring me some of their dust and I can cure George\'s back pain.', 'Her derde deva bir iksir yapacağım.', 'I am going to make a cure-all potion.', 'Evet, işte bu toz.', 'Yes, this is the dust.', 'Büyü Tozu', 'Sorcery Dust'),
82927: ('talk', None, 'İksiri Dene', 'Taste Test', 'Hah hah, başardım! Şimdi bu iksiri George\'a götür, tadına baksın. İçtiği an bel ağrısı geçecek.', 'Ha ha, it worked! Take this potion to George and let him taste it. The moment he drinks it, his back pain will be gone.', 'Çabuk, içsin şunu.', 'Hurry, make him drink it.', '(George iksiri bir dikişte içti) Aman tanrım, bu zehir mi? Ne kadar da kötü!', '(George gulps the potion down) Good grief, is this poison? It tastes awful!'),
82928: ('talk', None, 'Bana Eziyet Etmeyin!', 'Stop Tormenting Me!', 'Yalvarırım bana eziyet etmeyi bırakın! Çok acı çekiyorum! Beni susturmak mı istiyorsunuz? Aaaah! (George epey acı çekiyor gibi görünüyor.)', 'I beg you, stop tormenting me! It hurts so much! Are you trying to silence me for good? Aaargh! (George looks like he is in real pain.)', 'Bırak beni! Öleyim daha iyi!', 'Leave me alone! Just let me die!', 'Hah hah hah, yine olmadı…', 'Ha ha ha, failed again…'),
82929: ('collect', '污染者', 'Kirletici Cübbesi', 'Defiler\'s Robe', 'Pis Kirleticiler! Ormanı bile bile yok ediyor, canlıları zehirliyorlar. Onları öldürmeme yardım eder misin? Yapabilirsen giydikleri cübbeleri getir, gücünü kanıtla.', 'Filthy Defilers! They ruin the forest on purpose and poison every living thing. Will you help me kill them? If you can, bring back the robes they wear to prove your strength.', 'Sakın sana da bulaşmasınlar.', 'Do not let them taint you.', 'Harika, ne kadar çirkin olduklarını onlara göstereceğim.', 'Wonderful, I will show them how ugly they are.', 'Kirletici Cübbesi', 'Defiler\'s Robe'),
82930: ('kill', None, 'Kirliliği Önle', 'Stop the Pollution', 'Yozlaşmış Koru\'nun kirlenmesini önle! Kirleticileri durdur! Öldür!', 'Stop the pollution of the Fallen Woodland! Stop the Defilers! Kill!', 'Sağ bırakma!', 'Leave none alive!', 'İyi iş çıkardın, orayı kurtarmalıyız.', 'Well done, we must save that place.'),
82931: ('talk', None, 'Asıl Katil Kim', 'Who Is the Killer', 'Kardeşim Paul öldürüldü. Orman Muhafız Subayı\'na sorar mısın, katil kim? Kardeşimi öldürmeye kim cüret eder!', 'My brother Paul has been killed. Could you ask the Forest Guard Officer who did it? Who would dare to kill my brother!', 'Katili bulacağım!', 'I will find the killer!', 'Ne? George\'un kardeşi mi öldürülmüş?', 'What? George\'s brother was killed?'),
82932: ('collect', '☆剧毒撕裂者', 'Katili Ara', 'Find the Killer', 'Yılların tecrübesiyle söylüyorum, ☆Zehirli Parçalayıcılardan şüpheleniyorum. Çok gizli hareket ederler; görüş alanlarına girersen sonun gelmiş demektir. Kayıp Koru\'dalar. Bir ipucu bulursan doğrudan George\'a söyle.', 'From my years of experience, I suspect the ☆Venomous Rippers. They move in secret, and if they see you, your end has come. They are in the Lost Woodland. If you find a clue, tell George directly.', 'O yaratıklara dikkat et.', 'Be careful around those creatures.', 'Aaah, Paul\'un intikamını alacağım!', 'Aaah, I will avenge Paul!', 'Paul\'un Hatırası', 'Paul\'s Keepsake'),
82933: ('kill', None, 'Kardeşimin İntikamı', 'Revenge for My Brother', 'Canım kardeşim, nasıl da feci öldün, hüüü… İntikamını alacağım. Dostum, sen olmasan kardeşimin ölümünün gerçeğini asla öğrenemezdim. Bir kez daha yardım et, o ☆Zehirli Parçalayıcıların hepsini öldür!', 'My dear brother, what a terrible death, boo-hoo… I will avenge you. Friend, without you I would never have learned the truth. Help me once more: kill every one of those ☆Venomous Rippers!', 'Hüüü hüüü…', 'Boo-hoo…', 'Sağ ol, hüüü hüüü…', 'Thank you, boo-hoo…'),
82934: ('talk', None, 'Troller Don mu Giyer?', 'Do Trolls Wear Underpants?', 'Çok tuhaf, buradaki troller don giyiyor?! James\'e sorar mısın, bunun sebebi ne?', 'How strange, the trolls here wear underpants?! Could you ask James what the reason is?', 'Çirkin troller don giyiyor.', 'Ugly trolls in underpants.', 'Benden ne istiyorsun?', 'What do you want from me?'),
82935: ('collect', '☆鬼巨魔', 'Don Topla', 'Collect Underpants', 'Onlardan birinin donunu bana getir, incelemek istiyorum. Yozlaşmış Koru\'da yaşıyorlar.', 'Bring me the underpants of one of them, I want to study them. They live in the Fallen Woodland.', 'Ne tuhaf.', 'How odd.', '(Don mide bulandırıcı bir koku yayıyor) Bu da ne böyle.', '(The underpants give off a sickening smell) What on earth is this.', 'Trol Donu', 'Troll Underpants'),
82936: ('talk', None, 'Gaz Bombası!!', 'Stink Bomb!!', 'Bu donu generale götür de trolleri inceleme sevdasından vazgeçsin. Bu resmen delilik.', 'Take these underpants to the General so he gives up his idea of studying trolls. This is pure madness.', '(James yere kustu) İğrenç.', '(James throws up on the floor) Disgusting.', 'Ah, çok pis kokuyor! Bu resmen gaz bombası!', 'Argh, it stinks! This is a real stink bomb!'),
82937: ('kill', None, 'Belanızı Aradınız!!', 'Asking for Death!!', 'Beni kızdırdılar, bu resmen belayı aramak! Şu ☆Hayalet Trollerin canı cehenneme!', 'They made me angry, and that is asking for death! To hell with those ☆Ghost Trolls!', '(General yere kustu) Bu gerçekten iğrenç.', '(The General throws up on the floor) This is truly disgusting.', 'Hah hah, iyi iş genç!', 'Ha ha, well done, youngster!'),
81767: ('kill', None, 'Vebalı Yarasalar', 'Plague Bats', 'Sıkı savunmamız sayesinde ☆tarikatçılar buraya sızıp ortalığı karıştıramadı. Ama geceleri yeşil yarasalar ortaya çıkıyor. Belki de trollere hastalığı bulaştırıp onları değiştiren bu yarasalardır. Onları öldürürsek işler düzelebilir.', 'Thanks to our tight defense the ☆cultists have never slipped out to cause trouble. But at night some green bats appear. Perhaps these bats infected the trolls and made them mutate. Kill the bats and things may take a turn for the better.', 'Tarikat sandığımız kadar basit değilmiş.', 'The cult is not as simple as we thought.', 'Yarasalar temizlendi; troller artık kudurmayacak.', 'With the bats cleansed, the trolls will no longer go berserk.'),
# ===== Trol Ormanı =====
80476: ('collect', '森林巨魔', 'Anlaşılmaz Bir Merak', 'A Peculiar Hobby', 'Şehir Beyi\'nin tuhaf merakından şikâyet edecek değilim; bütün vaktim ormandaki şu canavarlarla, trollerle uğraşmakla geçiyor. Evet, bedenleri taş gibi olan bu yaratıklara karşı elimden pek bir şey gelmiyor. Onlarla aptalca güç yarıştırmak istemem. Bu işi denemek ister misin?', 'I will not complain about the Lord\'s odd hobby, because all my time goes to dealing with the monsters of this forest: the trolls. Yes, these rock-hard brutes leave me almost helpless, and I am not fool enough to match strength with them. Want to try this challenge?', 'Bu ormanın her yanı tuhaflık dolu.', 'Everything about this forest is strange.', 'Sakın bana fıkra anlatıp birbirlerinin boynuzlarını söktürdüğünü söyleme.', 'Do not tell me you got them to pull out each other\'s horns by telling jokes.', 'Trol Boynuzu', 'Troll Horn'),
80474: ('talk', None, 'Uzun Yol', 'The Long Journey', 'Elimden gelse seninle dönerdim ama görevim bununla bitmiyor. Geldiğin yoldan dön ve bunları Şehir Beyi\'ne ver. Bu işi hâlâ hatırlıyor mu, onu da bilmiyorum.', 'If I could, I would go back with you, but my duties do not end here. Follow the road you came by and hand these to the Lord. I wonder if he even remembers this matter.', 'Burada fazla uzun kaldım.', 'I have been here far too long.', 'Trol boynuzu mu? Bunlarla ne yapmak istediğimi hatırlamam biraz zaman alacak.', 'Troll horns? I will need some time to remember what I wanted them for.'),
81741: ('collect', '☆饥饿的巨魔', 'Daha Çok Boynuz', 'More Horns', 'Belki de dikkatimizi şu yeşil trollere vermeliyiz. Orman Trollerinden açıkça farklı gördüğüm tek şey bu. Git, bir dene.', 'Perhaps we should turn our attention to those green trolls. That is the one clear difference from the Forest Trolls that I can see. Go and give it a try.', 'Orman Trollerinden daha saldırgan görünüyorlar.', 'They seem more aggressive than the Forest Trolls.', 'Bunlarla Şehir Beyi memnun kalır sanırım.', 'With these, I think the Lord will be satisfied.', 'Yeşil Boynuz', 'Green Horn'),
81742: ('kill', None, 'Lanet Pusucular', 'Damned Ambushers', 'Bu iri kıyım ahmakların pusu kurabileceği hiç aklıma gelmezdi; büyük bir keşif bu. Burada yıllardır yaşamanın verdiği çeviklik olmasa şimdi ardımdan ancak dua edebilirdin. Şu Yıkıcılara günlerini göstermeliyim.', 'I never imagined these big oafs could set an ambush. What a discovery. Without the quick wits I gained from living here so long, you would now only be able to pray for me. I must teach those Destroyers a lesson.', 'Onlarla baş etmek için kafa yorman gerek.', 'You will need to use your head to deal with them.', 'Yumruklarından nasıl kaçtın?', 'How did you dodge their fists?'),
81743: ('talk', None, 'Dolgun Ücret', 'A Handsome Fee', 'Altını sevmeyen yoktur; sana verdiğim iş kadar kolayı da yok. Biraz yorulman yeter, dolgun bir ücret alırsın. Daha ne düşünüyorsun, bu paketi Şehir Beyi\'ne götür.', 'Nobody dislikes gold, and no job is as easy as the one I am giving you. Just spend a little effort and you earn a handsome fee. Why hesitate? Take this package to the Lord.', 'Bu lanet yerden nefret ediyorum.', 'I hate this damned place.', 'Vay, her gelişinde beni şaşırtıyorsun.', 'Wow, you surprise me every time you come.'),
# ===== Guanlin Kasabası: ana zincirin devamı ve Güneşli Orman görevleri =====
82555: ('kill', None, 'Yaban Domuzu Derdi', 'Boar Trouble', 'Güneşli Orman\'daki domuzlar gitgide çoğalıyor ve gündelik hayatımızı fena hâlde aksatıyor. Bu yaban domuzları çok saldırgandır. Bize biraz yaşam alanı açmalısın.', 'The boars of the Sunny Forest keep multiplying and are seriously disrupting our daily life. These wild boars are very aggressive. I think you should clear some living space for us.', 'Hâlâ burada ne arıyorsun?', 'What are you still doing here?', 'İyi iş çıkardın genç.', 'Well done, youngster.'),
81704: ('kill', None, 'Engerek Çetesi', 'The Viper Gang', 'Guanlin Kasabası öteden beri oduncuklukla geçinir. Güçlerine güvenen bazı tembeller odun kesip dönen kasabalıları soymaya başladı! Son günlerde iş iyice azıttı; gelip geçen tüccarlar da zarar görüyor, kasabanın adı lekeleniyor. Git ve onları adalete teslim et.', 'Guanlin Town has always lived off logging. Some idlers who rely on their strength have begun robbing townsfolk on their way back from cutting wood! Lately it has gotten worse; passing merchants suffer too, and the town\'s reputation is ruined. Go and bring them to justice.', 'Lanet Engerek Çetesi, başlarına gelecek var!', 'Damned Viper Gang, they have it coming!', 'Harika, görünen o ki elinden iş geliyor!', 'Excellent, it seems you do have some skill!'),
81705: ('talk', None, 'Muhtara Müjde', 'Report to the Mayor', 'Seni küçümsemişim. Kim bilir, belki bir gün benim gibi büyük bir milis komutanı olursun! Tecrübeme göre artık başarılarını muhtara anlatabilirsin.', 'It seems I underestimated you. Who knows, one day you might become a great militia captain like me! In my experience, it is time to report your great deeds to the Mayor.', 'Gelecek vaat eden bir çocuk.', 'A promising kid.', 'Bu harika! Tam da adama ihtiyacımız vardı!', 'This is wonderful! We are short of hands!'),
81706: ('collect', '蜘蛛', 'Aklını Kullan', 'Use Your Wits', 'Engerek Çetesi laftan anlamıyor; onlara acıyı tattırmalıyız! Güneşli Orman Kuzey\'e git, birkaç örümcek öldür ve bana örümcek salgısı getir. Ne işe yarayacağını biz biliriz. (Muhtar tuhaf bir kahkaha attı.)', 'The Viper Gang will not listen to reason, so we must make them suffer! Go to Sunny Forest North, kill some spiders and bring me spider slime. We have our uses for it. (The Mayor lets out a strange laugh.)', 'Şu haydut Engerek Çetesi! Onlara gününü göstermezsem beni kolay lokma sanarlar!', 'Those Viper Gang bandits! If I do not teach them a lesson, they will think I am a pushover!', 'Bu, planımızın ilk adımı.', 'This is the first step of our plan.', 'Örümcek Salgısı', 'Spider Slime'),
81707: ('kill', None, 'Engerek Çetesine Ceza', 'Punish the Viper Gang', 'Tamam, zehri silahına sürdüm. Git, Engerek Çetesi Seçkinlerini kes; acı içinde ölsünler! Bitirince Milis Komutanı ile konuş. Adamlarım ceza yöntemlerime hayran kalsın!', 'Good, I have smeared the venom on your weapon. Go and cut down the Viper Gang Elites, and let them die in agony! When you are done, talk to the Militia Captain. I want my men to admire my methods of punishment!', 'Ceza yöntemlerim hep pek ustacadır, öyle değil mi?', 'My methods of punishment are always so clever, are they not?', 'Muhtar böyle mi oldu…', 'So the Mayor has become like this…'),
81708: ('kill', None, 'Lanet Sinekler', 'Hateful Flies', 'Güneşli Orman Güney\'de sinek kadar iğrenç Yaramaz Periler var; insanın sinirini bozuyorlar! Silahınla onlara beni kızdırmanın sonunu göster! Bitirince Milis Komutanı ile konuş. Adamlarım ceza yöntemlerime hayran kalsın!', 'In Sunny Forest South there are Prankster Fairies as disgusting as flies, and they get on my nerves! Show them with your weapon what happens to those who anger me! When you are done, talk to the Militia Captain. I want my men to admire my methods of punishment!', 'O iğrenç sinekler gücümü tatsın!', 'Let those disgusting flies taste my power!', 'Ne kadar acımasızca!', 'How cruel!'),
81643: ('kill', None, 'Engerek Çetesini Temizle', 'Clear Out the Viper Gang', 'Engerek Çetesi artık Guanlin Kasabası\'na zarar veremiyor. Bu fırsatı kaçırmayalım, hepsini Güneşli Orman\'dan sürelim. Başaracağına inanıyorum! Geriye yalnızca ☆Engerek Çetesi Kasapları kaldı.', 'The Viper Gang can no longer harm Guanlin Town, so let us seize this chance and drive them all out of the Sunny Forest. I believe you can do it! Only the ☆Viper Gang Butchers are left.', 'Buraya bir daha adım atmasınlar.', 'Do not let them set foot here again.', 'Guanlin Kasabası\'na huzurunu geri verdin, teşekkürler.', 'You have brought peace back to Guanlin Town. Thank you.'),
81632: ('kill', None, 'Seçkin Muhafızlar', 'Elite Guards', 'Bu görev çok zorlu. Üstesinden gelip gelemeyeceğini en iyi sen bilirsin; ama gözlerinden kendine güvendiğini okuyorum, o yüzden sana inanıyorum. ☆Seçkin Muhafızlar Güneşli Orman Doğu\'nun derinliklerinde.', 'This task is very hard. Only you know whether you can handle it, but I can see in your eyes that you are full of confidence, so I believe in you. The ☆Elite Guards are deep in Sunny Forest East.', 'Umarım sağ salim dönersin.', 'I hope you come back safely.', 'Sandığımdan çok daha güçlüymüşsün!', 'You are much stronger than I imagined!'),
81626: ('talk', None, 'Kayıt', 'Sign Up', 'Hey, oradaki genç! Bu günlerde Guanlin Kasabası\'nda çok eğlenceli bir etkinlik var. Seni Orman Korucusu\'na önerdim bile; hemen git, kaydını yaptır.', 'Hey, you there, youngster! Guanlin Town is holding a very interesting event these days. I have already recommended you to the Forest Ranger, so hurry and sign up with him.', '', '', 'Oo! Gerçekten güçlü görünüyorsun.', 'Oh! You really do look strong.'),
81627: ('kill', None, 'Büyük Yılan Avı', 'The Great Snake Hunt', 'Bu etkinlikte Güneşli Orman\'ın güneyindeki engerekler yok edilecek. Bu yaratıklar artık biz insanlardan korkmuyor. Git ve onlara insan gücünün ne kadar büyük olduğunu göster!', 'The goal of this event is to wipe out the vipers in the south of the Sunny Forest. These creatures no longer fear us humans. Go and show them how mighty human strength is!', 'Senden çok şey bekliyorum.', 'I expect great things from you.', 'Evet! Beni hayal kırıklığına uğratmadın!', 'Yes! You did not disappoint me!'),
81628: ('talk', None, 'Jessie\'ye Haber Ver', 'Tell Jessie', 'Bu etkinlikte çok başarılıydın ve büyük takdir topladın. Git, bunu Jessie\'ye anlat. Seninle gurur duyacaktır.', 'You performed brilliantly in this event and earned high praise. Go and tell Jessie about it. She will surely be proud of you.', '', '', 'Harikasın! Beklediğimin çok üstünde!', 'You are amazing! Far beyond what I expected!'),
80035: ('kill', None, 'Periler ve Yılanlar', 'Fairies and Snakes', 'Aaah, Güneşli Orman Güney\'de neden bu kadar çok sinir bozucu yaratık var? Orada bir türlü rahat uyuyamıyorum. Sen, evet sen, başkasına bakma, sana diyorum: git, onların işini bitir.', 'Aaah, why are there so many annoying creatures in Sunny Forest South? They never let me sleep in peace there. You, yes you, do not look at anyone else, I mean you: go and get rid of them for me.', 'Hâlâ burada ne dikiliyorsun?', 'Why are you still standing here?', 'Oley! İyi iş!', 'Oh yeah! Nicely done!'),
81620: ('collect', '☆毒蛇帮虐杀者', 'Kasapların Zırhı', 'The Butchers\' Armor', 'Guanlin milislerini güçlendirmek için onlara sağlam zırh yaptırmam gerek. Duyduğuma göre ☆Engerek Çetesi Kasaplarının giydiği zırh bu iş için çok iyiymiş. Haydi genç, bana birkaç tane getir.', 'To strengthen the Guanlin militia I need to forge sturdy armor for them. I hear the armor worn by the ☆Viper Gang Butchers is an excellent choice. Go on, youngster, bring me some.', 'Bu zırhlar milisleri güçlendirmenin en önemli şartı.', 'This armor is the key to making the militia stronger.', 'Güzel, beni hayal kırıklığına uğratmadın.', 'Good, you did not disappoint me.', 'Kasap Zırhı', 'Butcher Armor'),
81644: ('collect', '☆精英护卫', 'Seçkin Zırh', 'Elite Armor', 'Güneşli Orman Doğu\'daki ☆Seçkin Muhafızlar gitgide çoğalıyor. Oraya gidip zırhlarını toplamanı istiyorum; ne kadar çok olursa o kadar iyi. Vakit dar, çabuk git gel.', 'The ☆Elite Guards in Sunny Forest East keep growing in number. I need you to go there and collect their armor, the more the better. Time is short, so be quick.', 'Buradaki milisleri güçlü kılacağım.', 'I will make the militia here strong.', 'Teşekkürler, bu kadarı yeter. Şimdi zırhları dövmeye başlayacağım.', 'Thank you, this is enough. Now I will start forging the armor.', 'Seçkin Zırh Parçası', 'Elite Armor Plate'),
81621: ('talk', None, 'Durumu Bildir', 'Report In', 'Milis Komutanı\'na Kasapların püskürtüldüğünü söylemeni istiyorum. Umarım bundan sonraki işleri o düzenler.', 'Please tell the Militia Captain that the Butchers have been driven back. I hope he can arrange what comes next.', '', '', 'Haber verdiğin için sağ ol. Posta güverciniyle üstlerime danışmam gerek.', 'Thank you for letting me know. I need to send a carrier pigeon and consult my superiors.'),
81622: ('talk', None, 'Yeni Görev', 'A New Task', 'Bence şimdi gevşemenin sırası değil; en azından Engerek Çetesi meselesi tam çözülmedi. Sıradaki yeni görevin bu.', 'I do not think this is the time to relax. At the very least, the Viper Gang problem is not fully solved. That is your next task.', '', '', 'Hmm… Mesele gerçekten de tam çözülmüş değil.', 'Hmm… The matter really is not fully settled.'),
81648: ('talk', None, 'Guanlin\'in Umudu', 'The Hope of Guanlin', 'Kasaba huzursuz; hain Sadinman intikam planını hazırlamaya başladı. Guanlin Kasabası yok mu olacak? Bunu mutlaka engellemelisin. Çabuk, Halk Koruyucusu\'na git ve bu işi görüş.', 'The town is in turmoil, and the traitor Sadinman has begun preparing his revenge. Is Guanlin Town about to be destroyed? You must stop this from happening. Quickly, go and discuss it with the Tribune.', '', '', 'Genç, durum ciddi. Guanlin Kasabası\'nı mutlaka kurtarmalısın.', 'Youngster, the situation is grave. You must save Guanlin Town.'),
81649: ('talk', None, 'Guanlin\'in Kurtarıcısı', 'The Savior of Guanlin', 'Artık çok güçlendin; herkes seni Guanlin Kasabası\'nın kurtarıcısı olarak görüyor. Burayı mutlaka kurtarmalısın, sana güveniyoruz. Milis Komutanı\'na söyle, sana destek olsun; Sadinman mutlaka yok edilmeli.', 'You have grown very strong, and everyone sees you as the savior of Guanlin Town. You must save this place, we are counting on you. Tell the Militia Captain to support you. Sadinman must be destroyed.', '', '', 'Cesur genç, git ve bir mucize yarat.', 'Brave youth, go and work a miracle.'),
81650: ('kill', None, 'Sadinman\'a Meydan Oku', 'Challenge Sadinman', 'Git, Sadinman\'a meydan oku. Mutlaka sağ dön!', 'Go and challenge Sadinman. Make sure you come back alive!', 'Silahını al ve savaş!', 'Take your weapon and fight!', 'Sadinman yenildi mi? Bu bir mucize! Sen kasabayı kurtaran kahramansın!', 'Sadinman has been defeated? It is a miracle! You are the hero who saved the town!'),
81651: ('talk', None, 'Guanlin\'in Kahramanı', 'The Hero of Guanlin', 'Harika, sen bizim kahramanımızsın; Sadinman bir daha buraya saldırmaya cesaret edemez. Muhtara git, hak ettiğin ödülü verecek.', 'Wonderful, you are our hero, and Sadinman will never dare attack this place again. Go to the Mayor, he will give you the reward you deserve.', '', '', 'Vay! Demek herkesi kurtaran sensin; kahramanlar genç yaşta çıkarmış. Bu hak ettiğin ödül, al.', 'Well! So you are the one who saved everyone. Heroes truly do emerge young. This is the reward you deserve, take it.'),
}
import re as _re
HAND = set(map(int, _re.findall(r'\{ id: (\d+)', open('www/js/tr.js', encoding='utf-8').read())))
nxt = {}
for i, t0 in T.items():
    n = t0['nextTaskId']
    if n in Q and (i in Q or i in HAND): nxt[n] = i
out = []
for i, v in Q.items():
    t = T[i]; typ, src = v[0], v[1]; ev = (t.get('events') or [{}])[0]
    q = {'id': i, 'giver': npc(t['acceptNpcId']), 'to': npc(t['deliverNpcId']), 'type': typ}
    assert q['giver'] and q['to'], (i, t['acceptNpcId'], t['deliverNpcId'])
    mon = ev.get('targetName') if typ == 'kill' else src
    if typ in ('kill', 'collect'):
        sid = scene_of(mon); assert sid, (i, mon)
        q.update(target=mon, count=ev['count'], sc=S[sid]['name']); r = S[sid].get('lvr'); q['lv'] = r[1] if r else (S[sid].get('lv') or 10)
        if typ == 'collect': q['chance'] = 1 if ev['count'] == 1 else 0.5
    if i in nxt: q['req'] = nxt[i]
    rw = t.get('rewards') or {}; q['rw'] = {'gold': rw.get('gold', 0), 'items': [[str(x['itemId']), x['count']] for x in rw.get('items', [])]}
    q['tr'] = [v[2], v[4], OK[0], v[6], v[8]] + ([v[10]] if len(v) > 10 else []); q['en'] = [v[3], v[5], OK[1], v[7], v[9]] + ([v[11]] if len(v) > 11 else [])
    out.append(q)
# görevin ırkı: veren NPC'nin bulunduğu haritanın tarafı (tools/taraf.py: APK muhafız tablosu + komşuluk); NPC farklı taraflarda birden çok yerdeyse bölge dosyasının "irk" alanı
import subprocess as _sp, collections as _col
_sp.run(['python3', 'tools/taraf.py'], check=True, stdout=_sp.DEVNULL)
TARAF = json.load(open('kaynak/apk/taraflar.json')); _LOC = _col.defaultdict(set)
for _sid, _s in S.items():
    for _e in _s['ents']: _LOC[_e[1]].add(TARAF.get(_sid, 'ortak'))
def taraf(npc, yedek=None):
    v = _LOC.get(npc) or set()
    if len(v) == 1: return next(iter(v))
    v2 = v - {'ortak'}
    return next(iter(v2)) if len(v2) == 1 else (yedek or 'ortak')
for q in out: q['race'] = taraf(q['giver'], '人类'); q['race'] == 'ortak' and q.pop('race')
# bölge çeviri dosyalarından otomatik aktarılan görevler (tools/gorev_aktar.py + kaynak/ceviri/gorevler/<ad>.json)
import glob, os
have = {q['id'] for q in out} | HAND
# görev yapıları: bütün bölge kaynak dosyalarından (bir çeviri dosyası birden çok bölgenin görevini içerebilir)
YAPI = {}
for K in sorted(glob.glob('kaynak/ceviri/gorevler/*_kaynak.json')):
    for s0 in json.load(open(K, encoding='utf-8')): YAPI.setdefault(s0['id'], s0)
for f in sorted(glob.glob('kaynak/ceviri/gorevler/*.json')):
    if f.endswith('_kaynak.json'): continue
    C = json.load(open(f, encoding='utf-8'))
    skip = set(C.get('atla', [])); n0 = len(out)
    for i in sorted(map(int, C['gorevler'])):
        s0 = YAPI.get(i); c = C['gorevler'][str(i)]
        if not s0: print('  yapı yok:', i); continue
        if i in have or i in skip or not c: continue
        q = {k: s0[k] for k in ('id', 'giver', 'to', 'type', 'target', 'targets', 'node', 'count', 'sc', 'chance', 'req', 'rw') if k in s0}
        if str(i) in C.get('zincir', {}): q['req'] = C['zincir'][str(i)]   # elle verilen zincir bağı
        if str(i) in C.get('sahneler', {}): q['sc'] = C['sahneler'][str(i)]   # hedefin asıl haritası (araç yanlış seçtiyse)
        if str(i) in C.get('teslim', {}): q.update(type='deliver', give=C['teslim'][str(i)], count=1)   # eşya getirme (çantadaki eşya teslim edilir)
        if str(i) in C.get('ozel', {}): q.update(type='special', flag=C['ozel'][str(i)])                 # oyundaki bir olayla biter (ör. kuluçka)
        if str(i) in C.get('hedefler', {}): q['g'] = C['hedefler'][str(i)]                               # elle yazılmış hedef cümlesi [tr, en]
        if str(i) in C.get('seviyeler', {}): q['lvMin'] = C['seviyeler'][str(i)]
        rc = C.get('irklar', {}).get(str(i)) or taraf(q['giver'], C.get('irk'))   # ırk: göreve özel > veren NPC'nin haritasının tarafı > bölge dosyası
        if rc and rc != 'ortak': q['race'] = rc
        if C.get('seviye') and q['type'] not in ('kill', 'collect', 'pickup'): q['lv0'] = C['seviye']   # şehirde verilen konuşma görevinin en düşük seviyesi
        if q['type'] in ('kill', 'collect', 'pickup'):
            nm = s0.get('sc'); r = next((x.get('lvr') for x in S.values() if x['name'] == nm and x.get('lvr')), None)
            q['lv'] = r[1] if r else 10
        if C.get('lv'): q['lvMin'] = max(q.get('lvMin', 0), C['lv']); q['lv'] = C['lv'] + 2   # zindan görevleri: haritanın seviye aralığı yok, dosyadaki seviye
        def arr(a):
            a = list(a); item = a[4] if len(a) > 4 else ''
            return [a[0], a[1], OK[0] if a is c['tr'] else OK[1], a[2], a[3]] + ([item] if item else [])
        q['tr'] = arr(c['tr']); q['tr'][2] = OK[0]; q['en'] = arr(c['en']); q['en'][2] = OK[1]
        out.append(q); have.add(i)
    # zincir bağı: elenen ya da atlanan görevin yerine bir önceki geçerli görev
    print(os.path.basename(f), 'görev', len(out) - n0)
ids = {q['id'] for q in out} | HAND
for q in out:
    if q.get('req') and q['req'] not in ids: q.pop('req')
# konuşma görevlerinin seviyesi: zincirdeki ya da aynı kişideki savaş görevinden
byg = {}
for q in out:
    if 'lv' in q: byg.setdefault(q['giver'], q['lv'])
# hedefi bir NPC olan "kullan/ver" görevleri (iksiri Gary'ye içir): NPC'ye dokununca biter
npcs = {q['giver'] for q in out} | {q['to'] for q in out}
for q in out:
    if q['type'] == 'pickup' and q.get('node') in npcs: q['use'] = 1
for q in out:
    if 'lv' not in q: q['lv'] = byg.get(q['giver']) or byg.get(q['to']) or 10
js = """// Görevler: tools/gorevler.py üretir; elle değiştirme. Yapı Android sürümünün görev tablosundan, metinler çevrildi.
'use strict';
(function () {
  const E = LANG === 'en', Q = %s;
  for (const q of Q) {
    const s = E ? q.en : q.tr, to = trName(q.to), sc = q.sc ? trName(q.sc) : '', mon = q.target ? trName(q.target) : '';
    q.title = s[0]; q.text = s[1]; q.ok = s[2]; q.wait = s[3]; q.done = s[4]; if (s[5]) q.item = s[5];
    const many = q.targets && q.targets.map(x => `${x[1]} ${trName(x[0])}`).join(', ');   // çok hedefli
    q.goal = q.g ? (E ? q.g[1] : q.g[0]) : q.type === 'deliver' ? (E ? `Bring ${q.item} to ${to}.` : `${q.item} eşyasını ${to} kişisine getir.`) : q.type === 'kill' ? (E ? `Kill ${many || q.count + ' ' + mon} in ${sc}, then talk to ${to}.` : `${sc}: ${many || q.count + ' ' + mon} öldür, sonra ${to} ile konuş.`)
      : q.type === 'collect' ? (E ? `Collect ${q.count} ${q.item} from ${mon} in ${sc}, then talk to ${to}.` : `${sc}: ${mon} canavarlarından ${q.count} ${q.item} topla, sonra ${to} ile konuş.`)
      : q.use ? (E ? `Use the ${q.item} on ${trName(q.node)}, then talk to ${to}.` : `${q.item} eşyasını ${trName(q.node)} üzerinde kullan, sonra ${to} ile konuş.`)
      : q.type === 'pickup' ? (E ? `Gather ${q.count} ${q.item} in ${sc}, then talk to ${to}.` : `${sc}: ${q.count} ${q.item} topla, sonra ${to} ile konuş.`)
      : q.item ? (E ? `Take the ${q.item} to ${to}.` : `${q.item} eşyasını ${to} kişisine götür.`)
      : (E ? `Talk to ${to}.` : `${to} ile konuş.`);
    delete q.tr; delete q.en; QUESTS.push(q);
  }
})();
""" % json.dumps(out, ensure_ascii=False, separators=(',', ':'))
open('www/js/quests_gen.js', 'w', encoding='utf-8').write(js)
print('görev', len(out))
